-- paperdollResources.typeID:  the apparel type a paperdoll resource needs (the NeX wardrobe).
-- generated by a one-off script from the Crucible client bulkdata 2001600003.cache2 (paperdollResources)
--
-- Why:  the client bulk header is paperdollResourceID, resGender, resPath, restrictions, typeID;  the server table had
--  no typeID (20261012120800-client-sync-resources.sql synced the other columns).  Saving a recustomized look checks
--  that every worn resource's type is owned (src/eve-server/store/Wardrobe.cpp), and ObjCacheDB sends the column so
--  the server's paperdollResources matches the client header.  230 resources have a typeID (214 distinct):  -1 on six
--  black monocle variants and 4055 (in no invTypes) on resource 1072 are kept as the client has them;  neither can be
--  owned, so only ROLE_CONTENT can wear those.  All other resources stay NULL (free to wear).
--
-- Idempotent:  ADD / DROP COLUMN IF (NOT) EXISTS;  the UPDATE sets the same values again.
-- Down:  the server's paperdollResources cache query reads typeID, so it fails without the column.

-- +migrate Up
ALTER TABLE `paperdollResources`
  ADD COLUMN IF NOT EXISTS `typeID` int(11) DEFAULT NULL;

CREATE TEMPORARY TABLE `pd_types` (
  `paperdollResourceID` int(11) NOT NULL,
  `typeID` int(11) NOT NULL,
  PRIMARY KEY (`paperdollResourceID`)
);
UPDATE `paperdollResources` r JOIN `pd_types` t USING (`paperdollResourceID`) SET r.`typeID` = t.`typeID`;
DROP TEMPORARY TABLE `pd_types`;

-- +migrate Down
ALTER TABLE `paperdollResources`
  DROP COLUMN IF EXISTS `typeID`;
